"use client";

import { useEffect, useMemo, useState } from "react";
import {
  CheckCircle2,
  Clock3,
  Filter,
  MessageSquare,
  Search,
  ShieldAlert,
  X,
} from "lucide-react";

import AdminShell from "../../components/AdminShell";
import { adminApi, ClientQuery } from "../../lib/adminApi";

type QueryFilter = "ALL" | "OPEN" | "ASSIGNED" | "ESCALATED" | "RESOLVED";

export default function Queries() {
  const [queries, setQueries] = useState<ClientQuery[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const [search, setSearch] = useState("");
  const [status, setStatus] = useState<QueryFilter>("ALL");

  const [selected, setSelected] = useState<ClientQuery | null>(null);
  const [resolution, setResolution] = useState("");
  const [busy, setBusy] = useState(false);

  async function loadQueries() {
    try {
      setLoading(true);
      setError("");

      const result = await adminApi.queries.list(
        status === "ALL" ? undefined : status,
      );

      setQueries(result);
    } catch (err) {
      if (
        err instanceof Error &&
        err.message === "ADMIN_AUTH_REQUIRED"
      ) {
        window.location.href = "/login";
        return;
      }

      setError(
        err instanceof Error
          ? err.message
          : "Unable to load client queries.",
      );
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadQueries();
  }, [status]);

  const filteredQueries = useMemo(() => {
    const term = search.trim().toLowerCase();

    if (!term) {
      return queries;
    }

    return queries.filter((query) =>
      [
        query.id,
        query.subject,
        query.category,
        query.priority,
        query.status,
        query.description,
      ]
        .filter(Boolean)
        .some((value) =>
          String(value).toLowerCase().includes(term),
        ),
    );
  }, [queries, search]);

  const counts = useMemo(() => {
    return {
      open: queries.filter((q) => q.status === "OPEN").length,
      assigned: queries.filter((q) => q.status === "ASSIGNED").length,
      escalated: queries.filter((q) => q.status === "ESCALATED").length,
      resolved: queries.filter((q) => q.status === "RESOLVED").length,
    };
  }, [queries]);

  async function resolveQuery() {
    if (!selected) {
      return;
    }

    if (resolution.trim().length < 5) {
      setError("Enter a clear resolution.");
      return;
    }

    try {
      setBusy(true);
      setError("");

      await adminApi.queries.resolve(
        selected.id,
        resolution.trim(),
      );

      setSelected(null);
      setResolution("");

      await loadQueries();
    } catch (err) {
      setError(
        err instanceof Error
          ? err.message
          : "Unable to resolve query.",
      );
    } finally {
      setBusy(false);
    }
  }

  return (
    <AdminShell>
      <div className="space-y-8">
        {/* Heading */}
        <div className="flex flex-col justify-between gap-4 lg:flex-row lg:items-end">
          <div>
            <p className="text-xs font-bold uppercase tracking-[0.14em] text-[#397b0a]">
              Customer operations
            </p>

            <h1 className="mt-1 text-3xl font-extrabold tracking-tight text-[#111827]">
              Client Queries
            </h1>

            <p className="mt-2 max-w-2xl text-sm text-[#6b7280]">
              Review, manage and resolve client support requests.
            </p>
          </div>

          <button
            type="button"
            onClick={loadQueries}
            disabled={loading}
            className="rounded-xl border border-[#dce3df] bg-white px-4 py-2.5 text-sm font-bold text-[#374151] shadow-sm transition hover:bg-[#f8faf9] disabled:opacity-50"
          >
            {loading ? "Refreshing..." : "Refresh"}
          </button>
        </div>

        {/* Error */}
        {error ? (
          <div className="flex items-start gap-3 rounded-2xl border border-red-200 bg-red-50 p-5">
            <ShieldAlert
              size={20}
              className="mt-0.5 shrink-0 text-red-600"
            />

            <div>
              <p className="text-sm font-bold text-red-800">
                Query operation failed
              </p>

              <p className="mt-1 text-xs text-red-700">
                {error}
              </p>
            </div>
          </div>
        ) : null}

        {/* Statistics */}
        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
          <QueryStat
            label="Open"
            value={counts.open}
            icon={MessageSquare}
            tone="blue"
          />

          <QueryStat
            label="Assigned"
            value={counts.assigned}
            icon={Clock3}
            tone="amber"
          />

          <QueryStat
            label="Escalated"
            value={counts.escalated}
            icon={ShieldAlert}
            tone="red"
          />

          <QueryStat
            label="Resolved"
            value={counts.resolved}
            icon={CheckCircle2}
            tone="green"
          />
        </div>

        {/* Main panel */}
        <section className="overflow-hidden rounded-2xl border border-[#e3e8e5] bg-white shadow-sm">
          {/* Panel header */}
          <div className="border-b border-[#e3e8e5] p-5">
            <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
              <div>
                <h2 className="text-base font-extrabold text-[#111827]">
                  Support queue
                </h2>

                <p className="mt-1 text-xs text-[#6b7280]">
                  Live client query records from OakPay.
                </p>
              </div>

              <div className="flex flex-col gap-3 sm:flex-row">
                {/* Search */}
                <div className="flex h-10 items-center gap-2 rounded-xl border border-[#dce3df] bg-[#f8faf9] px-3">
                  <Search
                    size={16}
                    className="text-[#9ca3af]"
                  />

                  <input
                    type="search"
                    value={search}
                    onChange={(event) =>
                      setSearch(event.target.value)
                    }
                    placeholder="Search queries..."
                    className="w-full bg-transparent text-sm outline-none placeholder:text-[#9ca3af] sm:w-56"
                  />
                </div>

                {/* Status */}
                <div className="flex h-10 items-center gap-2 rounded-xl border border-[#dce3df] bg-white px-3">
                  <Filter
                    size={16}
                    className="text-[#6b7280]"
                  />

                  <select
                    value={status}
                    onChange={(event) =>
                      setStatus(
                        event.target.value as QueryFilter,
                      )
                    }
                    className="bg-transparent text-sm font-medium text-[#374151] outline-none"
                  >
                    <option value="ALL">All statuses</option>
                    <option value="OPEN">Open</option>
                    <option value="ASSIGNED">Assigned</option>
                    <option value="ESCALATED">Escalated</option>
                    <option value="RESOLVED">Resolved</option>
                  </select>
                </div>
              </div>
            </div>
          </div>

          {/* Table */}
          <div className="overflow-x-auto">
            <table className="min-w-full text-left">
              <thead className="bg-[#f8faf9]">
                <tr className="border-b border-[#e3e8e5]">
                  <th className="px-6 py-4 text-xs font-bold uppercase tracking-wide text-[#6b7280]">
                    Query
                  </th>

                  <th className="px-6 py-4 text-xs font-bold uppercase tracking-wide text-[#6b7280]">
                    Subject
                  </th>

                  <th className="px-6 py-4 text-xs font-bold uppercase tracking-wide text-[#6b7280]">
                    Category
                  </th>

                  <th className="px-6 py-4 text-xs font-bold uppercase tracking-wide text-[#6b7280]">
                    Priority
                  </th>

                  <th className="px-6 py-4 text-xs font-bold uppercase tracking-wide text-[#6b7280]">
                    Status
                  </th>

                  <th className="px-6 py-4 text-right text-xs font-bold uppercase tracking-wide text-[#6b7280]">
                    Action
                  </th>
                </tr>
              </thead>

              <tbody>
                {loading ? (
                  <tr>
                    <td
                      colSpan={6}
                      className="px-6 py-14 text-center text-sm text-[#6b7280]"
                    >
                      Loading client queries...
                    </td>
                  </tr>
                ) : filteredQueries.length === 0 ? (
                  <tr>
                    <td
                      colSpan={6}
                      className="px-6 py-14 text-center"
                    >
                      <MessageSquare
                        size={28}
                        className="mx-auto text-[#cbd5d0]"
                      />

                      <p className="mt-3 text-sm font-bold text-[#374151]">
                        No queries found
                      </p>

                      <p className="mt-1 text-xs text-[#6b7280]">
                        Try changing your search or status filter.
                      </p>
                    </td>
                  </tr>
                ) : (
                  filteredQueries.map((query) => (
                    <tr
                      key={query.id}
                      className="border-b border-[#edf1ef] last:border-b-0 hover:bg-[#fafcfb]"
                    >
                      <td className="whitespace-nowrap px-6 py-4">
                        <span className="text-sm font-bold text-[#111827]">
                          {query.id}
                        </span>

                        <p className="mt-1 text-xs text-[#9ca3af]">
                          {formatDate(query.createdAt)}
                        </p>
                      </td>

                      <td className="max-w-xs px-6 py-4">
                        <p className="truncate text-sm font-semibold text-[#374151]">
                          {query.subject}
                        </p>
                      </td>

                      <td className="px-6 py-4 text-sm text-[#6b7280]">
                        {query.category}
                      </td>

                      <td className="px-6 py-4">
                        <StatusBadge
                          value={query.priority}
                          type="priority"
                        />
                      </td>

                      <td className="px-6 py-4">
                        <StatusBadge
                          value={query.status}
                          type="status"
                        />
                      </td>

                      <td className="px-6 py-4 text-right">
                        <button
                          type="button"
                          onClick={() => {
                            setSelected(query);
                            setResolution(
                              query.resolution || "",
                            );
                            setError("");
                          }}
                          className="rounded-lg bg-[#145323] px-3 py-2 text-xs font-bold text-white transition hover:bg-[#0b3a1c]"
                        >
                          Open query
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>

          {/* Footer */}
          <div className="border-t border-[#e3e8e5] bg-[#fafcfb] px-6 py-4">
            <p className="text-xs text-[#6b7280]">
              Showing{" "}
              <span className="font-bold text-[#374151]">
                {filteredQueries.length}
              </span>{" "}
              of{" "}
              <span className="font-bold text-[#374151]">
                {queries.length}
              </span>{" "}
              loaded queries.
            </p>
          </div>
        </section>
      </div>

      {/* Detail modal */}
      {selected ? (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white shadow-2xl">
            <div className="flex items-start justify-between border-b border-[#e3e8e5] px-6 py-5">
              <div>
                <p className="text-xs font-bold uppercase tracking-[0.12em] text-[#397b0a]">
                  Client query
                </p>

                <h2 className="mt-1 text-xl font-extrabold text-[#111827]">
                  {selected.subject}
                </h2>

                <p className="mt-1 text-xs text-[#6b7280]">
                  {selected.id} · {selected.category}
                </p>
              </div>

              <button
                type="button"
                onClick={() => setSelected(null)}
                className="rounded-lg p-2 text-[#6b7280] hover:bg-[#f5f7f6] hover:text-[#111827]"
                aria-label="Close query"
              >
                <X size={20} />
              </button>
            </div>

            <div className="space-y-6 p-6">
              <div className="grid gap-4 sm:grid-cols-3">
                <DetailItem
                  label="Priority"
                  value={selected.priority}
                />

                <DetailItem
                  label="Status"
                  value={selected.status}
                />

                <DetailItem
                  label="Created"
                  value={formatDate(selected.createdAt)}
                />
              </div>

              <div>
                <p className="mb-2 text-xs font-bold uppercase tracking-wide text-[#6b7280]">
                  Description
                </p>

                <div className="rounded-xl bg-[#f8faf9] p-4 text-sm leading-6 text-[#374151]">
                  {selected.description ||
                    "No description provided."}
                </div>
              </div>

              <div>
                <label
                  htmlFor="resolution"
                  className="mb-2 block text-sm font-bold text-[#111827]"
                >
                  Resolution
                </label>

                <textarea
                  id="resolution"
                  value={resolution}
                  onChange={(event) =>
                    setResolution(event.target.value)
                  }
                  rows={5}
                  placeholder="Enter the resolution provided to the client..."
                  className="w-full rounded-xl border border-[#dce3df] px-4 py-3 text-sm text-[#111827] outline-none transition placeholder:text-[#9ca3af] focus:border-[#397b0a] focus:ring-2 focus:ring-[#397b0a]/10"
                />
              </div>

              <div className="flex flex-col-reverse justify-end gap-3 border-t border-[#e3e8e5] pt-5 sm:flex-row">
                <button
                  type="button"
                  onClick={() => setSelected(null)}
                  className="rounded-xl border border-[#dce3df] px-5 py-3 text-sm font-bold text-[#374151] hover:bg-[#f8faf9]"
                >
                  Close
                </button>

                {selected.status !== "RESOLVED" ? (
                  <button
                    type="button"
                    disabled={busy}
                    onClick={resolveQuery}
                    className="rounded-xl bg-[#397b0a] px-5 py-3 text-sm font-bold text-white transition hover:bg-[#2f6808] disabled:cursor-not-allowed disabled:opacity-50"
                  >
                    {busy
                      ? "Resolving..."
                      : "Resolve query"}
                  </button>
                ) : null}
              </div>
            </div>
          </div>
        </div>
      ) : null}
    </AdminShell>
  );
}

function QueryStat({
  label,
  value,
  icon: Icon,
  tone,
}: {
  label: string;
  value: number;
  icon: typeof MessageSquare;
  tone: "green" | "blue" | "amber" | "red";
}) {
  const styles = {
    green: "bg-green-50 text-green-700",
    blue: "bg-blue-50 text-blue-700",
    amber: "bg-amber-50 text-amber-700",
    red: "bg-red-50 text-red-700",
  };

  return (
    <div className="rounded-2xl border border-[#e3e8e5] bg-white p-5 shadow-sm">
      <div className="flex items-start justify-between">
        <div>
          <p className="text-xs font-bold uppercase tracking-wide text-[#6b7280]">
            {label}
          </p>

          <p className="mt-2 text-3xl font-extrabold text-[#111827]">
            {value}
          </p>
        </div>

        <div
          className={`flex h-10 w-10 items-center justify-center rounded-xl ${styles[tone]}`}
        >
          <Icon size={19} />
        </div>
      </div>
    </div>
  );
}

function StatusBadge({
  value,
  type,
}: {
  value: string;
  type: "status" | "priority";
}) {
  const normalized = value.toUpperCase();

  let style = "bg-gray-100 text-gray-700";

  if (type === "priority") {
    if (normalized === "URGENT") {
      style = "bg-red-50 text-red-700";
    } else if (normalized === "HIGH") {
      style = "bg-orange-50 text-orange-700";
    } else if (normalized === "NORMAL") {
      style = "bg-blue-50 text-blue-700";
    }
  }

  if (type === "status") {
    if (normalized === "RESOLVED") {
      style = "bg-green-50 text-green-700";
    } else if (normalized === "ESCALATED") {
      style = "bg-red-50 text-red-700";
    } else if (normalized === "ASSIGNED") {
      style = "bg-blue-50 text-blue-700";
    } else if (normalized === "OPEN") {
      style = "bg-amber-50 text-amber-700";
    }
  }

  return (
    <span
      className={`inline-flex rounded-full px-2.5 py-1 text-[11px] font-bold ${style}`}
    >
      {value.replaceAll("_", " ")}
    </span>
  );
}

function DetailItem({
  label,
  value,
}: {
  label: string;
  value: string;
}) {
  return (
    <div className="rounded-xl bg-[#f8faf9] p-4">
      <p className="text-[10px] font-bold uppercase tracking-wide text-[#6b7280]">
        {label}
      </p>

      <p className="mt-1 text-sm font-bold text-[#111827]">
        {value}
      </p>
    </div>
  );
}

function formatDate(value: string) {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return "—";
  }

  return date.toLocaleString();
}